const gridTable=(cols,rows)=>{const grouped=cols.some(x=>typeof x==='object'),hasOp=cols.at(-1)==='操作';const head=grouped?`<tr>${cols.map(c=>typeof c==='object'?`<th colspan="${c.c.length}">${c.g}</th>`:`<th rowspan="2" class="${c==='操作'?'op':''}">${c}</th>`).join('')}</tr><tr>${cols.filter(c=>typeof c==='object').flatMap(c=>c.c.map(x=>`<th>${x}</th>`)).join('')}</tr>`:`<tr>${cols.map(x=>`<th class="${x==='操作'?'op':''}">${x}</th>`).join('')}</tr>`;return `<div class="tw"><table><thead>${head}</thead><tbody>${rows.length?rows.map((r,i)=>`<tr data-row="${i}">${r.map((x,j)=>`<td class="${hasOp&&j===r.length-1?'op':''}">${x??''}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="99" class="empty">暂无数据</td></tr>`}</tbody></table></div>`};
