function modal(title,body,buttons=[],wide=2){closeLayer();layer=document.createElement('div');layer.className='mask';layer.innerHTML=`<div class="dlg ${wide?'w'+wide:''}" role="dialog" aria-modal="true" aria-label="${title}"><div class="dh">${title}<span class="x" data-do="close">×</span></div><div class="db">${body}<div class="form-error" role="alert"></div></div><div class="df">${(buttons.length?buttons:[['关闭','close']]).map(([t,a,p])=>B(t,a,p)).join('')}</div></div>`;document.body.append(layer);layer.querySelector('input:not([type=file]),textarea,select')?.focus();}
