function vals(root=layer||document){const o={};root.querySelectorAll('[data-field]').forEach(e=>{o[e.dataset.field]=e.type==='checkbox'?e.checked:e.hasAttribute('contenteditable')?e.innerText:e.value});root.querySelectorAll('[data-switch]').forEach(e=>o[e.dataset.switch]=e.classList.contains('on'));return o}
