function pager(total,id='main'){const s=id==='main'?listState():(UX[id] ||= {page:1,size:10});const pages=Math.max(1,Math.ceil(total/s.size));s.page=Math.min(s.page,pages);return `<div class="pager" data-pager="${id}"><span>共 ${total} 条数据</span><span class="sp"></span>${sel('pageSize',[10,20,50],s.size,null)}${B('‹',`pg:${id}:${s.page-1}`)}${Array.from({length:Math.min(pages,7)},(_,i)=>`<span class="pg ${i+1===s.page?'on':''}" data-do="pg:${id}:${i+1}">${i+1}</span>`).join('')}${B('›',`pg:${id}:${s.page+1}`)}<span>跳至</span>${inp('jump',s.page,'type="number" min="1" max="'+pages+'" style="width:62px"')}${B('确定','jump:'+id)}<span>/ ${pages} 页</span></div>`}
function filterInput(f,q){if(f.type==='region')return ['省','市','区/县'].map((x,i)=>sel(f.l+i,[...new Set(REG.map(x=>x.split(' ')).filter(parts=>parts.slice(0,i).every((v,j)=>!q[f.l+j]||v===q[f.l+j])).map(parts=>parts[i]))],q[f.l+i]||'')).join('');if(f.type==='daterange')return inp(f.l+'起',q[f.l+'起']||'','type="date"')+'<span>至</span>'+inp(f.l+'止',q[f.l+'止']||'','type="date"');if(f.type==='select'){let options=f.opts||opts(f.l);if(['学校名称','学校'].includes(f.l)){const region=Object.entries(q).filter(([k])=>/区域[012]$/.test(k));options=options.filter(name=>region.every(([key,v])=>!v||REG[SCH.indexOf(name)]?.includes(v)));}return sel(f.l,options,q[f.l]||'');}return inp(f.l,q[f.l]||'',`placeholder="${esc(f.ph||'请输入')}"`)}
function filtersHTML(c,q){return `<div class="filters"><div class="fgrid">${(c.filters||[]).map(f=>`<div class="fi ${['region','daterange'].includes(f.type)?'span2':''}"><label>${f.l}</label><div class="ctl">${filterInput(f,q)}</div></div>`).join('')}</div><div class="factions">${B('查询','query',true)}${B('重置','reset')}</div></div>`}
const alias={'客户区域':'客户区域','问题类型':'反馈类型','反馈家长':'反馈家长','学校':'学校名称','学校名称':'学校名称','状态':'状态','所在区域':'所在区域','区域':'区域','归属区域':'所在地','角色':'角色','申请日期':'申请时间','抬头':'抬头','添加时间':'添加时间'};
function filteredRows(c,rows,q){return rows.map((cells,i)=>({cells,i})).filter(({cells})=>(state.active!=='refundOrder'||!listState().orderIds||listState().orderIds.some(id=>plain(cells[1]).includes(id)))&&Object.entries(q).every(([label,v])=>{if(!v)return true;const columns=flatCols(c.cols),timeIndex=columns.findIndex(x=>/时间|日期/.test(plain(x))),timeText=timeIndex<0?'':plain(cells[timeIndex]).slice(0,10);if(label==='时间范围'){if(v==='自定义')return true;const days=v==='近7天'?7:v==='近90天'?90:30;const date=new Date(timeText+'T00:00:00+08:00');return Number.isNaN(date.valueOf())||date.valueOf()>=Date.now()-days*86400000;}if(label==='自定义起')return timeText>=v;if(label==='自定义止')return timeText<=v;const cols=columns;const target=label.replace(/[起止]$/,'').replace(/\d$/,'');const j=cols.findIndex(x=>plain(x)===target||plain(x)===(alias[target]||target)||plain(x).includes(target));const text=j>=0?plain(cells[j]):cells.map(plain).join(' ');if(label.endsWith('起'))return text.slice(0,10)>=v;if(label.endsWith('止'))return text.slice(0,10)<=v;return text.toLowerCase().includes(String(v).toLowerCase())}))}
renderList=function(k,c){if(['statisticsHandle','holidaysConfig','holidaysConfigDetail','studentType','userFeedback','miniProgramShareConfig'].includes(k))return specialLists(k);if(!c.cols)return oldRenderList(k,c);const tc=conf(),s=listState(),rows=pageData();const result=filteredRows(tc,rows,s.q);s.total=result.length;const page=Math.min(s.page,Math.max(1,Math.ceil(result.length/s.size)));s.page=page;UX.visible=result.slice((page-1)*s.size,page*s.size);let h=c.back?backbar(c,c.headRight||''):'';if(c.infoTop)h+=`<div class="info">${c.infoTop}</div>`;if(c.pre)h+=c.pre;if(c.stats)h+=`<div class="stats" style="grid-template-columns:repeat(${c.stats.length},1fr)">${c.stats.map(x=>`<div class="stat" style="--c:${x.c}"><div class="n">${x.n}</div><div class="v">${x.v}<small>${x.u}</small></div><div class="d">${x.d}</div></div>`).join('')}</div>`;if(tc.compact)h+=compactHTML(tc,s);if(tc.filters)h+=filtersHTML(tc,s.q);if(tc.tabs)h+=`<div class="rtabs">${tc.tabs.map((t,i)=>`<span data-act="tab:${i}" class="${i===(state.tabIdx[k]||0)?'on':''}">${t.n}</span>`).join('')}</div>`;if(tc.toolbar||c.rightExport)h+=`<div class="toolbar">${(tc.toolbar||[]).map(b=>`<button class="btn pri" data-act="${b[1]}">${b[0]}</button>`).join('')}<div class="r">${c.rightExport?B('导出','exportTable'):''}</div></div>`;const cols=flatCols(tc.cols);h+=gridTable([...tc.cols,...(tc.ops?['操作']:[])],UX.visible.map(({cells,i})=>[...cells,...(tc.ops?[(typeof tc.ops==='function'?tc.ops(i):tc.ops).map(b=>b[1]==='none'?`<span class="lk gray">${b[0]}</span>`:lk(b[0],b[1],b[2]||'')).join('')]:[])]));return h+(c.noPager?'':pager(result.length));};
// Required field markers and values now participate in local form validation.
ctlHTML=function(f){let h=oldCtl(f);if(['input','password','textarea','select'].includes(f.type)){h=h.replace(/<(input|select|textarea) /,`<$1 data-label="${esc(f.l)}" ${f.req?'required ':''}`);if(f.v&&f.type==='select')h=h.replace(`>${esc(f.v)}</option>`,` selected>${esc(f.v)}</option>`)}return h};
const forms={};
renderForm=function(k,c){const row=UX.origin;let title=c.t;if((k==='schoolUserUpdate'||k==='regulatoryUserUpdate')&&row?.edit)title=title.replace('添加','编辑');const source=row?P[row.page]:null,cols=flatCols(source?.cols||[]);const view={...c,t:title,groups:c.groups.map(g=>({...g,f:g.f.map(f=>{const label=f.l.replace(/[：:]/g,''),j=cols.indexOf(label);return j>=0&&f.type==='text'?{...f,v:plain(row.cells[j])}:f})}))};return oldRenderForm(k,view)};
function captureRow(el){const row=el.closest('tr[data-row]');if(row && !layer){UX.row=+row.dataset.row;const vis=UX.visible?.[UX.row];UX.origin={page:state.active,index:vis?.i??UX.row,cells:vis?.cells||[],edit:/编辑/.test(el.textContent)};}}
function hydrate(){const k=state.active,c=P[k];if(c.type!=='form')return;const saved=forms[k];document.querySelectorAll('.card [data-label]').forEach(e=>{const key=e.dataset.label.replace(/[：:]/g,'');if(saved&&saved[key]!=null)e.value=saved[key];else if(UX.origin?.edit){const source=P[UX.origin.page];const cols=flatCols(source.cols||[]);const i=cols.findIndex(x=>x.replace(/[：:]/g,'')===key);if(i>=0)e.value=plain(UX.origin.cells[i]);}});}
