function validate(root){for(const e of root.querySelectorAll('[required]')){if(!String(e.value).trim()){e.focus();return error('请填写'+e.dataset.label)}}const pw=[...root.querySelectorAll('input[type=password]')].filter(x=>!/原密码/.test(x.dataset.label||''));if(pw.length>=2&&pw[0].value!==pw[1].value)return error('两次输入的密码不一致');return true}
function saveGeneric(){
 const root=layer||document.querySelector('.card');if(!validate(root))return;
 const values={};root.querySelectorAll('[data-label]').forEach(e=>values[e.dataset.label.replace(/[：:]/g,'')]=e.value);
 if(layer&&['invoiceAdd','invoiceReissue','phoneEdit'].includes(UX.dialog)){return error('此功能沿用原型展示，本次文档未给出完整业务规则；暂不模拟提交结果。');}
 if(!layer&&/Reset$/.test(state.active)){const p=P[state.active].parent;logDemo('重置账号密码',UX.origin?.cells?.map(plain).join(' · ')||P[state.active].t);if(p)openPage(p);toast('密码重置已演示，未修改真实账号');return;}
 if(layer){
   if(UX.dialog){const c=P[state.active];if(c.cols){const rows=pageData(),cols=flatCols(c.cols);let row=UX.origin?.page===state.active&&UX.origin.edit?rows[UX.origin.index]:null;
   if(!row){row=cols.map(x=>x.includes('时间')?now():x.includes('编号')?code('DEMO',++UX.seq):'--');rows.unshift(row)}
   cols.forEach((label,i)=>{const match=Object.keys(values).find(v=>label===v||label.replace(/名称$/,'')===v);if(match)row[i]=esc(values[match])});}}
   closeLayer();render();toast('已保存（本地演示）');
 }else{
   forms[state.active]=values;const p=P[state.active].parent;
   if(p){const c=P[p],rows=c.cols?(c._data ||= Array.from({length:c.total||0},(_,i)=>c.rows(i))):null;
     if(rows){const cols=flatCols(c.cols);let row=UX.origin?.page===p&&UX.origin.edit?rows[UX.origin.index]:null;
       if(!row){row=cols.map(x=>x.includes('时间')?now():x.includes('编号')?code('DEMO',++UX.seq):'--');rows.unshift(row)}
       cols.forEach((label,i)=>{if(values[label]!=null)row[i]=esc(values[label])});}
     openPage(p);
   }toast('已保存（本地演示）');
 }logDemo('保存',P[state.active].t);
}
openDialog=function(key){UX.dialog=key;if(key==='faqAdd')return faqDialog();if(key==='faqEdit')return faqDialog(0);if(key==='phoneCfg')return phoneDialog();if(key==='shareEdit')return shareEdit(0);if(['packageAdd','ship','statDetail','statStudents','prodDetail'].includes(key))return modal('请选择记录','请从对应学校、生产批次或统计记录进入，以确保展示和操作正确的数据。',[['关闭','close']],1);if(key==='feedback'||key==='feedbackDone'){if(!UX.origin||UX.origin.page!=='userFeedback')return modal('请选择记录','请从用户反馈记录进入。',[['关闭','close']],1);return feedbackDialog(UX.row);}oldDialog(key);const d=D[key];if(d?.f){const values=UX.origin?.edit?UX.origin:null;if(values){const cols=flatCols(P[values.page].cols||[]);layer.querySelectorAll('[data-label]').forEach(e=>{const i=cols.indexOf(e.dataset.label);if(i>=0)e.value=plain(values.cells[i])})}}};
openDrawer=function(key){oldDrawer(key);if(!UX.origin?.cells?.length)return;const row=UX.origin.cells;const cols=flatCols(P[UX.origin.page].cols||[]);layer.querySelectorAll('dt').forEach(dt=>{const i=cols.findIndex(c=>plain(c)===dt.textContent||plain(c).replace(/号$/,'编号')===dt.textContent);if(i>=0)dt.nextElementSibling.innerHTML=row[i]});};
// XLSX and ZIP downloads are real local files, with no external dependency.
const enc=new TextEncoder();
function zip(entries){const parts=[],central=[];let offset=0;const u16=(v,o,x)=>v.setUint16(o,x,true),u32=(v,o,x)=>v.setUint32(o,x>>>0,true);for(const [name,value]of entries){const n=enc.encode(name),b=typeof value==='string'?enc.encode(value):value;let crc=0xffffffff;for(const x of b){crc^=x;for(let j=0;j<8;j++)crc=crc>>>1^((crc&1)?0xedb88320:0)}crc=(crc^0xffffffff)>>>0;const local=new Uint8Array(30+n.length),v=new DataView(local.buffer);u32(v,0,0x04034b50);u16(v,4,20);u16(v,6,0x800);u32(v,14,crc);u32(v,18,b.length);u32(v,22,b.length);u16(v,26,n.length);local.set(n,30);parts.push(local,b);const c=new Uint8Array(46+n.length),cv=new DataView(c.buffer);u32(cv,0,0x02014b50);u16(cv,4,20);u16(cv,6,20);u16(cv,8,0x800);u32(cv,16,crc);u32(cv,20,b.length);u32(cv,24,b.length);u16(cv,28,n.length);u32(cv,42,offset);c.set(n,46);central.push(c);offset+=local.length+b.length;}const size=central.reduce((s,x)=>s+x.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);u32(ev,0,0x06054b50);u16(ev,8,entries.length);u16(ev,10,entries.length);u32(ev,12,size);u32(ev,16,offset);const out=new Uint8Array(offset+size+22);let at=0;for(const p of [...parts,...central,end]){out.set(p,at);at+=p.length}return out}
function xlsx(cols,rows){const xml=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>`;const cell=(x,i)=>{let col='',n=i+1;while(n){n--;col=String.fromCharCode(65+n%26)+col;n=Math.floor(n/26)}return `<c r="${col}" t="inlineStr"><is><t xml:space="preserve">${esc(plain(x))}</t></is></c>`};return zip([['[Content_Types].xml',xml+'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>'],['_rels/.rels',xml+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],['xl/workbook.xml',xml+'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="演示数据" sheetId="1" r:id="rId1"/></sheets></workbook>'],['xl/_rels/workbook.xml.rels',xml+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>'],['xl/worksheets/sheet1.xml',xml+'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'+[cols,...rows].map((r,i)=>`<row r="${i+1}">${r.map((v,j)=>cell(v,j).replace(/r="([A-Z]+)"/,`r="$1${i+1}"`)).join('')}</row>`).join('')+'</sheetData></worksheet>']])}
