/* 办理统计：唯一订单集合驱动六个状态视图及详情。 */
const statusNames=['当前在读办理汇总','待确认','待生产','生产中','已发货','已收货'];
const orders=Array.from({length:36},(_,i)=>{const school=Math.floor(i/6),status=statusNames[1+i%5],n=2+i%2;return {id:code('SS',i),school,student:KID[i%10],studentId:'S'+school+'-'+i%6,parent:NM[i%10],phone:demoPhones[i%10],grade:OPTS['年级'][i%5],cls:(i%3+1)+'班',created:dt(i),status,batch:['生产中','已发货','已收货'].includes(status)?'202610'+pad(10+i%19)+pad(i+1,5):'',confirmTime:dt(i),shipTime:dt(i-1),receiveTime:dt(i-2),carrier:'顺丰速运',tracking:'SF12345678'+pad(i,3),style:i%2?'魔术贴-方形':'别针款-方形',layout:'无证件照版',address:REG[school]+' '+SCH[school]+'门卫室',contact:NM[school],contactPhone:demoPhones[school],quantity:n,badges:Array.from({length:n},(_,j)=>({id:'XH'+pad(i+1,4)+pad(j+1),epc:'1D5A'+pad(i+1,10)+pad(j+1),gift:j===0,price:j===0?0:30,refund:j===1&&i%7===0&&['生产中','已发货','已收货'].includes(status)})),snapshot:{style:i%2?'魔术贴-方形':'别针款-方形',layout:'无证件照版',pdf:null}}});
let batchSequence=100;
function liveBadges(o){return ['待确认','待生产'].includes(o.status)?o.badges.filter(b=>!b.refund):o.badges}
function effectiveBadges(o){return o.badges.filter(b=>!b.refund)}
function effectiveMetrics(os){const valid=os.filter(o=>o.status!=='已取消'&&effectiveBadges(o).length),bs=valid.flatMap(effectiveBadges);return {people:new Set(valid.map(o=>o.studentId)).size,orders:valid.length,total:bs.length,gift:bs.filter(b=>b.gift).length,paid:bs.filter(b=>!b.gift).length,amount:bs.reduce((n,b)=>n+b.price,0)}}
function metrics(os){os=os.filter(o=>!['待确认','待生产'].includes(o.status)||liveBadges(o).length);const bs=os.flatMap(liveBadges);return {people:new Set(os.map(o=>o.studentId)).size,orders:os.length,total:bs.length,gift:bs.filter(b=>b.gift).length,paid:bs.filter(b=>!b.gift).length,amount:bs.reduce((a,b)=>a+b.price,0),refund:os.flatMap(o=>o.badges).filter(b=>b.refund).length,refundAmount:os.flatMap(o=>o.badges).filter(b=>b.refund).reduce((a,b)=>a+b.price,0)}}
const summary=os=>{const m=metrics(os);return `<div class="summary"><span class="tt">汇总统计</span><span>办理人数：<b>${m.people}</b></span><span>办理张数：<b>${m.total}</b></span><span>赠送张数：<b>${m.gift}</b></span><span>付费张数：<b>${m.paid}</b></span></div>`};
function statsHTML(){const ti=state.tabIdx.statisticsHandle||0,s=listState(),q=s.q;const c={filters:[RG('所在区域'),S('学校名称'),...(ti>=3?[I('订单批次号')]:[])]};const matches=orders.filter(o=>window.ZxhDataAccess?.canSchool(o.school)!==false&&o.status!=='已取消'&&(!['待确认','待生产'].includes(o.status)||liveBadges(o).length>0)&&(!ti||o.status===statusNames[ti])&&(!q['学校名称']||SCH[o.school]===q['学校名称'])&&(!q['订单批次号']||o.batch.includes(q['订单批次号']))&&[0,1,2].every(n=>!q['所在区域'+n]||REG[o.school].includes(q['所在区域'+n])));const groups=ti>=3?Object.values(Object.groupBy(matches,o=>o.batch)):Object.values(Object.groupBy(matches,o=>o.school));UX.statsGroups=groups;let cols,rows;const base=['所在区域','学校名称','年级/班级'];if(ti===0){cols=[...base,'在读学生数','未办人数','办理人数','赠送张数','付费张数','人均张数','总张数','操作'];rows=groups.map((os,i)=>{const o=os[0],m=metrics(os);return [REG[o.school],SCH[o.school],'全部',60,60-m.people,m.people,m.gift,m.paid,m.people?(m.total/m.people).toFixed(2):0,m.total,A('办理详情','statDrill:'+i)]});}else if(ti<=2){cols=[...base,'订单数','办理张数','赠送张数','付费张数','付费金额','操作'];rows=groups.map((os,i)=>{const o=os[0],m=metrics(os);return [REG[o.school],SCH[o.school],'全部',m.orders,m.total,m.gift,m.paid,yuan(m.amount),A('查看','prodView:'+i)+(ti===2?A('确认下单','batchConfirm:'+i):'')]});}else{cols=['订单批次号','学校名称',ti===3?'确认下单时间':ti===4?'发货时间':'收货时间','年级/班级','订单数','办理人数','办理张数','赠送张数','付费张数','付费金额','退款张数','退款金额','操作'];rows=groups.map((os,i)=>{const o=os[0],m=metrics(os);return [o.batch,SCH[o.school],ti===3?o.confirmTime:ti===4?o.shipTime:o.receiveTime,'全部',m.orders,m.people,m.total,m.gift,m.paid,yuan(m.amount),m.refund,yuan(m.refundAmount),A('明细导出','productionExport:'+i)+(ti===3?A('发货','ship:'+i):'')+A('查看','prodView:'+i)]});}s.total=rows.length;const max=Math.max(1,Math.ceil(rows.length/s.size));s.page=Math.min(s.page,max);let h=`<div class="rtabs">${statusNames.map((n,i)=>`<span class="${i===ti?'on':''}" data-act="tab:${i}">${n}</span>`).join('')}</div>`+filtersHTML(c,q);if(ti===1)h+='<div class="info">待学校确认校徽办理信息是否准确</div>';if(ti===2)h+='<div class="info">确认下单后，将锁定订单批次，请在“生产中”页面导出明细交于厂商进行校徽生产</div>';if(ti===0)h+=summary(matches);return h+gridTable(cols,rows.slice((s.page-1)*s.size,s.page*s.size))+pager(rows.length)}
function prodView(i){UX.group=UX.statsGroups[i];UX.prodFilter={};UX.prodPage={page:1,size:10};renderProd()}
function renderProd(){let os=UX.group;const q=UX.prodFilter||{};os=os.filter(o=>(!q['学生姓名']||o.student.includes(q['学生姓名']))&&(!q['家长信息']||o.parent.includes(q['家长信息'])||o.phone.includes(q['家长信息']))&&(!q['年级']||o.grade===q['年级'])&&(!q['班级']||o.cls===q['班级'])&&(!q['下单时间起']||o.created.slice(0,10)>=q['下单时间起'])&&(!q['下单时间止']||o.created.slice(0,10)<=q['下单时间止']));const c={filters:[S('年级'),S('班级'),I('学生姓名'),I('家长信息'),DR('下单时间')]};const post=['生产中','已发货','已收货'].includes(UX.group[0].status);const cols=['下单时间','下单家长','年级','班级','班级编号','入学年份','学生姓名','家长联系电话','校徽编号','证件照','办理总数','赠送张数','付费张数',...(post?['退款张数','退款EPC编号','EPC编号（十六进制）','二维码地址']:[])];const s=UX.prodPage;s.total=os.length;s.page=Math.min(s.page,Math.max(1,Math.ceil(os.length/s.size)));modal(UX.group[0].status+'订单详情',`<p class="context">当前：${SCH[UX.group[0].school]}${UX.group[0].batch?' · '+UX.group[0].batch:''}</p>`+filtersHTML(c,q).replaceAll('data-do="query"','data-do="prodQuery"').replaceAll('data-do="reset"','data-do="prodReset"')+gridTable(cols,os.slice((s.page-1)*s.size,s.page*s.size).map(o=>{const m=metrics([o]),bs=liveBadges(o);return [o.created,o.parent,o.grade,o.cls,'C'+o.school+o.cls[0],2026,o.student,o.phone,bs.map(b=>b.id).join('<br>'),'无需证件照',m.total,m.gift,m.paid,...(post?[m.refund,o.badges.filter(b=>b.refund).map(b=>b.epc).join('<br>')||'--',o.badges.map(b=>b.epc).join('<br>'),o.badges.map(b=>'https://example.com/badge/'+b.epc).join('<br>')]:[])]}))+pager(os.length,'prodPage'),[['关闭','close']],3);}
function drill(i){UX.drillSchool=UX.statsGroups[i][0].school;UX.drillMode=0;UX.drillQ={};UX.drillPage={page:1,size:10};renderDrill()}
function renderDrill(){const school=UX.drillSchool,all=orders.filter(o=>o.school===school&&o.status!=='已取消');const q=UX.drillQ||{};const os=all.filter(o=>(!q['年级']||o.grade===q['年级'])&&(!q['班级']||o.cls===q['班级']));if(UX.drillMode===0){const groups=Object.values(Object.groupBy(os,o=>o.grade+'-'+o.cls));UX.classGroups=groups;const rows=groups.map((g,i)=>{const m=metrics(g);return [g[0].grade,g[0].cls,10,10-m.people,m.people,m.gift,m.paid,(m.total/m.people).toFixed(2),m.total,A('查看明细','studentDrill:'+i)]});modal('办理详情',`<p class="context">当前：${SCH[school]}</p>`+summary(os)+filtersHTML({filters:[S('年级'),S('班级')]},q).replaceAll('data-do="query"','data-do="drillQuery"').replaceAll('data-do="reset"','data-do="drillReset"')+gridTable(['年级','班级','在读学生数','未办人数','办理人数','赠送张数','付费张数','人均张数','总张数','操作'],rows),[['关闭','close']],3);}else{const g=UX.classGroups[UX.drillClass];const result=g.filter(o=>!UX.studentQ||o.student.includes(UX.studentQ));modal('查看明细',A('← 返回','classBack')+`<span class="context">当前：${SCH[school]}-${g[0].grade}-${g[0].cls}</span>`+summary(g)+`<div class="compact">${inp('studentName',UX.studentQ||'','placeholder="学生姓名"')}${B('查询','studentQuery',true)}${B('重置','studentReset')}</div>`+gridTable(['序号','学生姓名','办理张数','赠送张数','付费张数','办理次数','最近一次下单时间'],result.map((o,i)=>{const m=metrics([o]);return [i+1,o.student,m.total,m.gift,m.paid,1,o.created]})),[['关闭','close']],3)}}
function confirmBatch(i){const os=UX.statsGroups[i];UX.group=os;const o=os[0];modal('确认下单','<div class="warnbar">请确认学校收货地址，若地址有误，请联系学校进行更改</div>'+kv([['学校',SCH[o.school]],['收货地址',o.address],['联系人',o.contact],['联系方式',o.contactPhone]])+'<p class="tip">确认后锁定本批次信息并进入生产中，历史快照不随学校资料变更。</p>',[['取消','close'],['确定','batchSave',true]],1)}
function saveBatch(){const os=UX.group;if(os.some(o=>o.status!=='待生产'))return error('订单状态已更新，请刷新后重试');if(os.some(o=>!o.address||!o.contact||!o.contactPhone))return error('学校收货信息不完整，请联系学校完善后重试');if(window.ZxhDelivery?.confirmBatch()===false)return error('确认下单失败，请稍后重试');const batch=today().replaceAll('-','')+pad(++batchSequence,5);os.forEach(o=>{o.batch=batch;o.status='生产中';o.confirmTime=now();o.snapshot=copy({...o.snapshot,address:o.address,contact:o.contact,phone:o.contactPhone,badges:o.badges});});logDemo('确认办理订单',batch,`锁定 ${os.length} 单`);closeLayer();render();toast('确认下单成功');}
function shipping(i){UX.group=UX.statsGroups[i];UX.shipVerified=null;modal('发货',kv([['订单批次',UX.group[0].batch],['学校',SCH[UX.group[0].school]]])+`<div class="frm">${field('物流公司',sel('carrier',OPTS['承运商'].filter(x=>x!=='EMS')),true)}${field('物流单号',inp('tracking','','placeholder="如 SF1234567890"'),true)}${field('',B('查询','trackQuery'))}</div><p id="tracking-result" class="tip">本地演示：查询不会连接物流服务。</p>`,[['取消','close'],['确定','shipSave',true]],1);layer.querySelector('[data-do="shipSave"]').disabled=true;}
function trackQuery(){const v=vals();if(!v.carrier)return error('请选择物流公司');if(!v.tracking)return error('请输入物流单号');if(!/^[A-Za-z0-9]{8,24}$/.test(v.tracking))return error('未查询到该物流单号，请核对后重试');UX.shipVerified={...v};layer.querySelector('#tracking-result').textContent='模拟查询结果：单号有效 · 运输中';layer.querySelector('[data-do="shipSave"]').disabled=false;layer.querySelector('.form-error').textContent='';}
function saveShip(){const v=vals();if(!UX.shipVerified||v.carrier!==UX.shipVerified.carrier||v.tracking!==UX.shipVerified.tracking)return error('请先查询并确认物流单号有效');if(UX.group.some(o=>o.status!=='生产中'))return error('订单状态已更新，请刷新后重试');UX.group.forEach(o=>Object.assign(o,{status:'已发货',carrier:v.carrier,tracking:v.tracking,shipTime:now()}));logDemo('录入物流信息',UX.group[0].batch,v.tracking);closeLayer();render();toast('发货成功（本地演示）');}
function exportProduction(i){UX.exportGroup=UX.statsGroups[i];const groups=Object.values(Object.groupBy(UX.exportGroup,o=>o.snapshot.style+'_'+o.snapshot.layout));modal('明细导出',`<div class="info">按下单时的款式和制作内容分组，过滤退款成功的校徽。明细以学校名称命名。</div>`+gridTable(['校徽款式','版式','有效校徽数','矢量文件'],groups.map(g=>[g[0].snapshot.style,g[0].snapshot.layout,g.flatMap(o=>o.badges.filter(b=>!b.refund)).length,g.some(o=>!o.snapshot.pdf)?tag('原始示例无PDF附件','o'):tag('已保留PDF快照')]))+'<p class="tip">订单导出模板的准确列名和顺序待核对，当前导出尚未定版。示例原型未附真实生产PDF和证件照。</p>',[['取消','close'],['下载演示生产包','productionDownload',true]],2)}
function productionDownload(){const groups=Object.values(Object.groupBy(UX.exportGroup,o=>o.snapshot.style+'_'+o.snapshot.layout));if(!groups.length){toast('暂无可导出的生产数据');return}groups.forEach(g=>{const rows=g.flatMap(o=>o.badges.filter(b=>!b.refund).map(b=>[o.id,o.batch,o.student,o.grade,o.cls,b.id,b.epc,'https://example.com/badge/'+b.epc,b.gift?'是':'否',b.price]));const entries=[[SCH[g[0].school]+'.xlsx',xlsx(['办理记录编号','订单批次号','学生姓名','年级','班级','校徽编号','EPC编号','二维码','是否赠送','单价'],rows)],['说明.txt','本文件为原型演示数据。已退款成功校徽已排除。示例原型没有真实工厂版式PDF/证件照，缺失文件未伪造。历史订单始终读取下单快照。']];const seen=new Set();g.forEach(o=>{const p=o.snapshot.pdf;if(p&&!seen.has(p.name)){seen.add(p.name);entries.push([p.name,new Uint8Array(p.bytes)])}});download(g[0].batch+'_'+g[0].snapshot.style+'_'+g[0].snapshot.layout+'.zip',zip(entries),'application/zip')});logDemo('导出数据',UX.group?.[0]?.batch||'生产包','下载分款式与版式生成的生产资料包');closeLayer();toast('演示生产包已生成');}

/* 学校配置与套餐：页面编辑态与已保存配置分开。 */
const schoolConfigs={};
const layouts=['完整字段版','无校徽编号版','无证件照版','无证件照且无校徽编号版'];
const styles=['别针款-方形','魔术贴-方形'];
function newConfig(){return {enabled:false,free:'免费办理',defaultQty:'3',maxQty:'10',minQty:'1',start:'1',end:'31',number:true,photo:false,numberRule:'学校代码+入学年份+流水号',numberGrades:'全部年级',photoSize:'1寸',photoBackground:'白底',photoRemark:'',photoSpec:'作为校徽头像，需上传1寸、白底标准证件照',title:'智能校徽申请与补办入口',shareTitle:'智能校徽登记办理与补办',detail:'',packages:[],cover:null,video:null}}
function requiredLayout(c){return c.photo?(c.number?0:1):(c.number?2:3)}
function fileInput(kind,accept,text='上传'){return `<label class="btn sm upload-label">${text}<input type="file" data-upload="${kind}" accept="${accept}" hidden></label>`}
function thumb(file){return file?.url?`<img src="${file.url}" alt="${esc(file.name)}" class="preview-thumb" data-do="image:${file.url}">`:'<span class="thumb"></span>'}
function schoolHTML(){const d=UX.configDraft ||= copy(schoolConfigs[UX.school]||newConfig());let h=backbar({t:'校徽活动配置 · '+SCH[UX.school]},B('取消','configBack')+B('保存','configSave',true));h+='<div class="frm" style="max-width:1000px"><div class="grp-t">基础设置</div>'+field('功能开关',switcher('enabled',d.enabled)+'<span>开启活动报名</span><div class="tip">控制小程序 banner 是否展示活动入口。</div>')+field('首张校徽',sel('free',['免费办理','不免费'],d.free,null),true)+field('起订数量',`<span>默认展示量</span>${sel('defaultQty',Array.from({length:10},(_,i)=>i+1),d.defaultQty,null)}<span>单次最多购买</span>${sel('maxQty',Array.from({length:10},(_,i)=>i+1),d.maxQty,null)}<span>首次至少购买</span>${sel('minQty',Array.from({length:10},(_,i)=>i+1),d.minQty,null)}`,true)+field('办理时间',`<span>每月</span>${sel('start',Array.from({length:31},(_,i)=>i+1),d.start,null)}<span>日至</span>${sel('end',Array.from({length:31},(_,i)=>i+1),d.end,null)}<span>日</span>`,true)+'<div class="grp-t">校徽办理信息</div>'+field('校徽制作内容',`<label class="chk"><input type="checkbox" checked disabled>学校名称/logo</label><label class="chk"><input type="checkbox" checked disabled>学生姓名</label><label class="chk"><input data-field="number" type="checkbox" ${d.number?'checked':''}>校徽编号</label><label class="chk"><input data-field="photo" type="checkbox" ${d.photo?'checked':''}>学生证件照</label><label class="chk"><input type="checkbox" checked disabled>德育二维码</label>`)+field('收集办理信息',`<div style="width:100%"><div class="sec">01 学生姓名　<span class="tip">固定不变</span></div><div class="sec">02 就读班级　<span class="tip">固定不变</span></div>${d.number?`<div class="sec">03 校徽编号　${A('编辑','numberEdit')}<p class="tip">编号规则：${esc(d.numberRule)}<br>编号效果：XH2026000001（示意）　适用年级：${esc(d.numberGrades)}</p></div>`:''}${d.photo?`<div class="sec">04 学生证件照　${A('编辑','photoEdit')}<p class="tip">照片规格：${esc(d.photoSpec)}　适用学生：全部学生</p></div>`:''}<div class="sec">05 德育二维码　<span class="tip">固定不变</span></div></div>`)+`<div class="grp-t">校徽套餐</div><div class="toolbar">${B('新增套餐','packageNew',true)}<span class="tip">当前必传：${layouts[requiredLayout(d)]} · PDF</span></div>`+gridTable(['套餐名称','制作样式','校徽款式','销售单价','适用年级','操作'],d.packages.map((p,i)=>[esc(p.name),thumb(p.preview),esc(p.style),yuan(p.price),p.grades.map(esc).join('、'),A('修改','packageEdit:'+i)+A('删除','packageDelete:'+i,true)]))+'<div class="grp-t" style="margin-top:24px">产品信息</div>'+field('标题名称',inp('title',d.title),true)+field('分享标题',inp('shareTitle',d.shareTitle),true)+field('分享封面',thumb(d.cover)+fileInput('cover','image/jpeg,image/png','上传图片')+'<span class="tip">建议 380 × 304</span>')+field('产品详情',`<div class="rte"><div class="bar">${['加粗','斜体','下划线'].map((x,i)=>`<button class="btn sm" data-do="rich:${['bold','italic','underline'][i]}">${x}</button>`).join('')}</div><div class="ed" data-field="detail" contenteditable="true">${esc(d.detail)}</div></div>`)+field('产品视频',(d.video?esc(d.video.name):'')+fileInput('video','video/mp4','上传视频')+'<span class="tip">建议 MP4、16:9</span>')+'<div class="form-error" role="alert"></div></div>';return h}
function configSave(){saveDraft();const d=UX.configDraft;if(!(1<=+d.minQty&&+d.minQty<=+d.defaultQty&&+d.defaultQty<=+d.maxQty))return error('购买数量设置不合理，请确保首次至少购买数量不大于默认展示量，且默认展示量不大于单次最多购买数量');if(+d.start>+d.end)return error('开始日期不能晚于结束日期');if(!d.title.trim())return error('请填写标题名称');if(!d.shareTitle.trim())return error('请填写分享标题');if(d.enabled&&!d.packages.length)return error('请先完善校徽套餐及活动信息后再开启活动');if(d.packages.some(p=>!p.files[requiredLayout(d)]))return error('请上传所有套餐当前必传版式的矢量文件');d.detail=document.querySelector('[contenteditable]')?.innerText||d.detail;if(window.ZxhDelivery?.configSave()===false)return error('保存失败，请重试');schoolConfigs[UX.school]=copy(d);UX.dirty=false;logDemo('修改校徽活动配置',SCH[UX.school],'保存整份学校配置；历史订单快照保持不变');toast('保存成功（本地演示）');}
function packageDialog(i=null){saveDraft();UX.packageIndex=i;UX.packageDraft=i===null?{name:'',style:styles[0],price:'',preview:null,grades:[],files:{}}:copy(UX.configDraft.packages[i]);renderPackage()}
function packageValues(){const v=vals();const p=UX.packageDraft;if(v.packageName!=null)p.name=v.packageName;if(v.packagePrice!=null)p.price=v.packagePrice;p.grades=[...layer.querySelectorAll('[data-grade]:checked')].map(x=>x.dataset.grade);}
function renderPackage(){const p=UX.packageDraft,required=requiredLayout(UX.configDraft);modal(UX.packageIndex===null?'新增校徽套餐':'修改校徽套餐',`<div class="frm">${field('选择款式',sel('packageStyle',styles,p.style,null),true)}${field('已选款式',esc(p.style))}${field('套餐名称',inp('packageName',p.name),true)}${field('销售单价',inp('packagePrice',p.price,'inputmode="decimal" placeholder="0.00"')+'<span>元</span>',true)}${field('制作样式',thumb(p.preview)+fileInput('packagePreview','image/jpeg,image/png','上传照片'),true)}${field('适用年级',['全部年级',...OPTS['年级']].map(g=>`<label class="chk"><input type="checkbox" data-grade="${g}" ${p.grades.includes(g)?'checked':''}>${g}</label>`).join(''),true)}</div><div class="grp-t">矢量文件（PDF）</div>${gridTable(['版式类型','状态','文件','操作'],layouts.map((l,i)=>[l,i===required?tag('当前必传','o'):'备用',esc(p.files[i]?.name||'暂未上传矢量文件'),fileInput('vector'+i,'.pdf,application/pdf',p.files[i]?'更换':'上传')+(p.files[i]?A('查看文件','vectorPreview:'+i):'')]))}<p class="tip">修改仅影响后续新订单；历史订单使用下单时的文件快照。</p>`,[['取消','packageCancel'],['确定','packageSave',true]],2);layer.querySelector('.x').dataset.do='packageCancel';}
function savePackage(){packageValues();const p=UX.packageDraft;if(!p.style)return error('请选择校徽款式');p.name=p.name.trim();if(!p.name)return error('请输入套餐名称');if(UX.configDraft.packages.some((x,i)=>i!==UX.packageIndex&&x.name===p.name))return error('套餐名称已存在，请重新输入');if(!/^\d+(\.\d{1,2})?$/.test(p.price))return error('请输入正确的销售单价');if(!p.preview)return error('请上传制作样式');if(!p.grades.length)return error('请选择适用年级');if(!p.files[requiredLayout(UX.configDraft)])return error('请上传当前必传版式的矢量文件');if(UX.packageIndex===null)UX.configDraft.packages.push(copy(p));else UX.configDraft.packages[UX.packageIndex]=copy(p);UX.dirty=true;closeLayer();UX.packageDraft=null;render();toast('套餐已加入编辑草稿，请保存页面使其生效');}
function packageDelete(i){const d=UX.configDraft;if(d.enabled&&d.packages.length===1)return ask('活动开启时至少保留一个有效套餐。',()=>{},'无法删除');ask('删除后家长将无法继续选择该套餐，是否确认删除？历史订单及其文件快照保留。',()=>{d.packages.splice(i,1);UX.dirty=true;render()})}
async function handleUpload(e){const kind=e.target.dataset.upload,file=e.target.files?.[0];if(!file)return;const vector=kind.startsWith('vector');if(vector){packageValues();if(!/\.pdf$/i.test(file.name))return error('仅支持上传 PDF 格式矢量文件');const bytes=Array.from(new Uint8Array(await file.arrayBuffer()));if(String.fromCharCode(...bytes.slice(0,5))!=='%PDF-')return error('文件内容不是有效PDF，请重新上传');UX.packageDraft.files[+kind.slice(6)]={name:file.name,bytes,url:URL.createObjectURL(file)};renderPackage();return;}if(kind==='video'){saveDraft();UX.configDraft.video={name:file.name,url:URL.createObjectURL(file)};render();return;}if(!/image\/(jpeg|png)/.test(file.type))return error('仅支持 JPG/PNG 图片');if(kind==='shareImage'&&file.size>2*1024*1024)return error('图片不能超过 2MB');const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('文件读取失败'));reader.readAsDataURL(file)});const dimensions=await new Promise(resolve=>{const img=new Image();img.onload=()=>resolve([img.naturalWidth,img.naturalHeight]);img.onerror=()=>resolve(null);img.src=url});if(!dimensions)return error('图片读取失败，请重新上传');if(kind==='shareImage'&&dimensions[0]*4!==dimensions[1]*5){return error('图片比例为 5:4');}const f={name:file.name,url};if(kind==='packagePreview'){packageValues();UX.packageDraft.preview=f;renderPackage();}else if(kind==='shareImage'){UX.shareDraft.title=vals().shareTitle;UX.shareDraft.image=f;renderShare();}else{saveDraft();UX.configDraft.cover=f;render();}}

