function feedbackHTML(){const c={filters:[RG('所在区域'),S('学校名称'),I('反馈家长'),S('问题类型'),S('状态',{opts:['待回复','已回复']}),I('反馈家长手机号')]},s=listState();let rows=feedbacks.map((f,i)=>({f,i,cells:[REG[f.school],SCH[f.school],parents[f.parent].name,parents[f.parent].phone.replace(/(\d{3})\d{4}/,'$1****'),f.child,f.type,esc(f.content),f.created,feedbackStatus(f)]}));rows=rows.filter(x=>(window.ZxhDataAccess?.canSchool(x.f.school)??true)&&Object.entries(s.q).every(([k,v])=>!v||(k==='反馈家长手机号'?parents[x.f.parent].phone.includes(v):k==='反馈家长'?parents[x.f.parent].name.includes(v):k==='问题类型'?x.f.type===v:k==='状态'?feedbackStatus(x.f)===v:k==='学校名称'?SCH[x.f.school]===v:REG[x.f.school].includes(v))));rows.sort((a,b)=>b.f.created.localeCompare(a.f.created)||b.i-a.i);s.total=rows.length;UX.feedbackRows=rows;s.page=Math.min(s.page,Math.max(1,Math.ceil(rows.length/s.size)));return filtersHTML(c,s.q)+gridTable(['所在区域','所在学校','反馈家长','反馈家长手机号','反馈关联孩子','反馈类型','反馈内容','反馈时间','状态','操作'],rows.slice((s.page-1)*s.size,s.page*s.size).map(x=>[...x.cells.slice(0,6),`<span class="ellipsis" title="${esc(x.f.content)}">${esc(x.f.content)}</span>`,x.f.created,tag(feedbackStatus(x.f),x.f.reply?'g':'o'),A(x.f.reply?'查看':'处理','feedback:'+x.i)]))+pager(rows.length)}
