function queryHTML(){const result=UX.results,p=UX.selectedParent===null?null:parents[UX.selectedParent];return `<div class="ph"><h2>用户数据快速查询</h2><p>以家长为中心聚合孩子、考勤、校徽、订单、退款、反馈记录</p></div><div class="sec"><div class="compact">${inp('parentQuery',UX.query,'placeholder="输入家长手机号/姓名进行查询" style="width:380px"')}${B('查询','parentQuery',true)}${B('重置','parentReset')}</div><p class="tip">手机号为精确查询；姓名为模糊查询，按姓名查询时，请先从匹配结果中选择正确的家长。</p></div><div class="two"><div class="panel"><b>查询结果</b><p class="tip">找到 ${result?.length||0} 位家长${result?.length?'，请选择':''}</p>${result?.length?result.map(i=>{const x=parents[i];return `<div class="pitem ${UX.selectedParent===i?'on':''}" data-do="parentSelect:${i}"><b>${x.name}</b>　${UX.selectedParent===i?tag('当前查看'):''}<p>${x.phone.replace(/(\d{3})\d{4}/,'$1****')}</p><p class="tip">关联孩子：${KID[i]}　关联学校：${SCH[i%6]}<br>最近登录时间：${dt(i)}</p></div>`}).join(''):'<div class="empty">'+(result?'无匹配家长':'请先查询家长')+'</div>'}</div><div class="panel">${p?parentDetail(p,UX.selectedParent):'<div class="empty">请从左侧选择要查看的家长</div>'}</div></div>`}
