function findParent(){const q=vals(document).parentQuery.trim();UX.query=q;UX.selectedParent=null;UX.queryTab=0;UX.parentOrderQ={};if(!q){UX.results=[];render();return toast('请输入家长手机号或姓名')}UX.results=parents.map((_,i)=>i).filter(i=>/^\d+$/.test(q)?parents[i].phone===q:parents[i].name.includes(q));if(UX.results.length===1)UX.selectedParent=UX.results[0];render()}
