function holidayEdit(i){UX.holidayDay=i;const d=holidayYears[UX.holidayYear||0].days[i];if(d.start<=today())return;modal('修改节假日/补班',`<div class="frm narrow">${field('节假日名称',esc(d.name))}${field('日期类型',d.type)}${field('开始日期',inp('holidayStart',d.start,`type="date" min="${nextDay()}"`),true)}${field('结束日期',inp('holidayEnd',d.end,`type="date" min="${nextDay()}"`),true)}</div><div class="warnbar">修改后需要发布，发布后次日生效；历史日期不受影响。</div>`,[['取消','close'],['确定','holidaySave',true]],1)}
function holidaySave(){const h=holidayYears[UX.holidayYear||0],d=h.days[UX.holidayDay],v=vals();if(!v.holidayStart||!v.holidayEnd)return error('请选择开始和结束日期');if(v.holidayStart<=today()||v.holidayEnd<=today())return error('仅可选择未来日期（明天及以后）');if(v.holidayStart.slice(0,4)!==h.year||v.holidayEnd.slice(0,4)!==h.year)return error('日期必须在当前配置年份内');if(v.holidayEnd<v.holidayStart)return error('结束日期不能早于开始日期');const changed=d.start!==v.holidayStart||d.end!==v.holidayEnd;Object.assign(d,{start:v.holidayStart,end:v.holidayEnd});h.status=h.status==='待发布'?'待发布':'已调整待发布';h.source='原型演示数据+人工调整';h.updated=now();if(changed)logDemo('修改节假日配置',h.year+'年 '+d.name,'节假日日期修改并保存成功');closeLayer();render();toast('修改已保存，发布后次日生效')}
function holidayFetch(i){const h=holidayYears[i];if(h.status==='已过期')return;ask(`${h.year}年：重新获取后，已发布配置将变为“已调整待发布”，需重新发布。<br><br>本原型未连接外部接口，此操作仅演示状态变化，保留原型日期，不伪造接口返回。`,()=>{h.status=h.status==='待发布'?'待发布':'已调整待发布';h.updated=now();h.source='原型演示数据';render();toast('已演示重新获取状态变化')},'重新获取')}
