document.addEventListener('click',e=>{if(e.target.classList.contains('mask')){e.stopImmediatePropagation();return;}const target=e.target.closest('[data-do]');if(target){e.preventDefault();e.stopImmediatePropagation();action(target.dataset.do);return;}const sw=e.target.closest('[data-switch]');if(sw){e.preventDefault();e.stopImmediatePropagation();sw.classList.toggle('on');sw.setAttribute('aria-checked',sw.classList.contains('on'));if(state.active==='schoolConfig'&&!layer)saveDraft();return;}const el=e.target.closest('[data-act]');if(!el)return;captureRow(el);const act=el.dataset.act;if(!el.closest('tr')&&((act.startsWith('dlg:')&&/Add$/i.test(act))||act==='page:contractAdd'||act==='page:schoolUserUpdate'||act==='page:regulatoryUserUpdate')){UX.origin=null;delete forms[act.slice(5)];}
 if(act==='back'&&state.active==='schoolConfig'){e.stopImmediatePropagation();action('configBack');return;}
 if(act.startsWith('tab:')&&state.active==='statisticsHandle'){e.stopImmediatePropagation();state.tabIdx[state.active]=+act.split(':')[1];const s=listState();s.q={};s.page=1;render();return;}
 if(act==='submit'){e.stopImmediatePropagation();if(P[state.active].type==='perm'){const key=permKey();perms[key]=[...document.querySelectorAll('.tree input')].map(x=>x.checked);toast('权限已保存（本地演示）');return;}saveGeneric();return;}
 if(act==='export'){e.stopImmediatePropagation();action('exportTable');return;}
 if(act.startsWith('confirm:')&&/删除/.test(act)&&UX.origin?.page===state.active){e.stopImmediatePropagation();const index=UX.origin.index;ask(act.slice(8),()=>{pageData().splice(index,1);render();toast('已删除演示记录')});return;}
 if(act.startsWith('toast:原型：表单已重置')){e.stopImmediatePropagation();delete forms[state.active];render();hydrate();return;}
 if(act==='page:transactionDetailsView'){UX.txRow=UX.origin;}
 if(act==='back'&&state.active==='viewAttendanceStatistics'){e.stopImmediatePropagation();openPage('userDataQuery');return;}
},true);
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-upload]')){handleUpload(e).catch(()=>error('文件读取失败，请重试'));return;}if(t.dataset.field==='pageSize'){const id=t.closest('[data-pager]').dataset.pager,s=id==='main'?listState():UX[id];s.size=+t.value;s.page=1;if(id==='prodPage')renderProd();else render();return;}if(state.active==='schoolConfig'&&!layer){saveDraft();if(['number','photo'].includes(t.dataset.field))render();}if(UX.packageDraft&&t.dataset.field==='packageStyle'){packageValues();const old=UX.packageDraft.style,next=t.value;if(old===next)return;t.value=old;ask('修改款式后，原版式矢量文件将清空，不影响历史订单，请确认。',()=>{UX.packageDraft.style=next;UX.packageDraft.files={};renderPackage()},'提示',renderPackage);return;}if(t.matches('[data-grade]')){if(t.dataset.grade==='全部年级'&&t.checked)layer.querySelectorAll('[data-grade]').forEach(x=>x.checked=x===t);else if(t.checked){const all=layer.querySelector('[data-grade="全部年级"]');if(all)all.checked=false;}return;}if(UX.shipVerified&&['carrier','tracking'].includes(t.dataset.field)){UX.shipVerified=null;layer.querySelector('[data-do="shipSave"]').disabled=true;layer.querySelector('#tracking-result').textContent='信息已修改，请重新查询。';}if(t.matches('.tree input')){const node=t.closest('.node');node.nextElementSibling?.querySelectorAll('input').forEach(x=>x.checked=t.checked);}},true);
document.addEventListener('input',e=>{const t=e.target;if(state.active==='schoolConfig'&&!layer)UX.dirty=true;if(t.dataset.field==='shareTitle'&&UX.shareDraft&&layer){const preview=document.getElementById('share-preview-title');if(preview)preview.textContent=t.value;}const count=t.parentElement.querySelector('.count');if(count&&t.maxLength>0)count.textContent=t.value.length+'/'+t.maxLength;if(['tracking','carrier'].includes(t.dataset.field)&&UX.shipVerified){UX.shipVerified=null;layer.querySelector('[data-do="shipSave"]').disabled=true;}},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(layer){if(layer.querySelector('[data-do=packageSave]'))action('packageCancel');else action('close');e.stopImmediatePropagation();}return;}if(e.key==='Enter'&&e.target.dataset.field==='parentQuery'){e.preventDefault();findParent();}if(e.key==='Enter'&&e.target.dataset.field==='loginName'){e.preventDefault();simulateLogin();}},true);
document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-drag]');if(row){UX.drag=row.dataset.drag;e.dataTransfer.setData('text/plain',UX.drag);}});
document.addEventListener('change',e=>{const t=e.target,root=t.closest('.filters');if(root&&/区域[012]$/.test(t.dataset.field||'')){const prefix=t.dataset.field.slice(0,-1),n=+t.dataset.field.slice(-1);for(let j=n+1;j<=2;j++){const next=root.querySelector(`[data-field="${prefix+j}"]`);if(next)next.value='';}const q=vals(root),parts=window.ZxhRegions.data.flatMap(p=>p.children.flatMap(c=>c.children.map(a=>[p.name,c.name,a.name])));for(let j=n+1;j<=2;j++){const next=root.querySelector(`[data-field="${prefix+j}"]`);if(next){const ready=Array.from({length:j},(_,k)=>q[prefix+k]).every(Boolean),values=ready?[...new Set(parts.filter(r=>r.slice(0,j).every((p,k)=>p===q[prefix+k])).map(r=>r[j]))]:[];next.disabled=!ready;next.innerHTML='<option value="">'+(ready?'全部':'暂无数据')+'</option>'+values.map(x=>`<option>${x}</option>`).join('');}}const school=root.querySelector('[data-field="学校名称"],[data-field="学校"]');if(school){school.innerHTML='<option value="">请选择</option>'+SCH.filter((_,i)=>[0,1,2].every(j=>!q[prefix+j]||REG[i].includes(q[prefix+j]))).map(x=>`<option>${x}</option>`).join('');}}if(root&&t.dataset.field==='年级'){const cls=root.querySelector('[data-field="班级"]');if(cls)cls.value='';}if(t.dataset.field==='时间范围'){const compact=t.closest('.compact');const following=compact.nextElementSibling;if(following?.classList.contains('custom-dates'))following.remove();if(t.value==='自定义')compact.insertAdjacentHTML('afterend',`<div class="filters custom-dates"><div class="fi"><label>创建时间</label><div class="ctl">${inp('自定义起','','type="date"')}<span>至</span>${inp('自定义止','','type="date"')}</div></div></div>`);}},true);
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drag]'))e.preventDefault()});
document.addEventListener('drop',e=>{const row=e.target.closest('[data-drag]');if(!row||!UX.drag)return;e.preventDefault();const [kind,from]=UX.drag.split(':'),[target,to]=row.dataset.drag.split(':');if(kind!==target||from===to)return;const list=kind==='faq'?faqs:studentTypes;const [item]=list.splice(+from,1);list.splice(+to,0,item);UX.drag=null;render();toast('排序已保存（本地演示）')});
window.addEventListener('beforeunload',e=>{if(state.active==='schoolConfig'&&UX.dirty){e.preventDefault();e.returnValue=''}});
render();













